function previewImage(e){const t=document.getElementById("preview-container"),i=document.getElementById("image-preview");if(e.files&&e.files[0]){const n=new FileReader;n.onload=function(e){i.src=e.target.result,t.classList.remove("hidden")},n.readAsDataURL(e.files[0])}else i.src="#",t.classList.add("hidden")}